def find_values(
    self, element: Union[str, BaseTag, Iterable[Union[str, BaseTag]]],
    load: bool = False
) -> Union[List[Any], Dict[Union[str, BaseTag], List[Any]]]:
    """Return the values for `element` found in the File-set.

    Parameters
    ----------
    element : str or BaseTag or iterable of str or BaseTag
        The element(s) to find values for.
    load : bool, optional
        If ``True`` then load the instances and return the values from
        the loaded instances, otherwise return the values from the
        directory records (default ``False``).

    Returns
    -------
    list or dict
        If `element` is a single element, a list of the unique values
        for `element` found in the File-set. If `element` is an iterable,
        a dict mapping each element to a list of its unique values.
    """
    if isinstance(element, (str, BaseTag)):
        elements = [element]
        single = True
    else:
        elements = list(element)
        single = False

    results: Dict[Union[str, BaseTag], List[Any]] = {
        ee: [] for ee in elements
    }
    for instance in self:
        if load:
            instance = instance.load()

        for ee in elements:
            if ee in instance:
                value = instance[ee].value
                if value not in results[ee]:
                    results[ee].append(value)

    if single:
        return results[elements[0]]

    return results

